def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Track opponent's recent behavior and outcomes
    last_me, last_opp = history[-1]

    # Count total opponent cooperation/defection
    opp_c = 0
    my_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1
    opp_d = n - opp_c

    # Always defect detection
    if n >= 6 and opp_d == n:
        return 'D'

    # Always cooperate detection
    if n >= 6 and opp_c == n:
        # cooperate but occasionally test to exploit
        if n >= 10 and n % 13 == 0 and n < 90:
            return 'D'
        return 'C'

    # Compute recent window
    window = 8
    start = n - window if n > window else 0
    recent_opp_d = 0
    recent_opp_c = 0
    recent_same = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            recent_opp_d += 1
        else:
            recent_opp_c += 1
        if history[i][0] == history[i][1]:
            recent_same += 1
    rlen = n - start

    # If recent opponent defection rate very high, defect
    if rlen >= 4 and recent_opp_d >= rlen - 1:
        return 'D'

    # Endgame: last few rounds, try to exploit cooperative opponents
    remaining = 100 - n
    if remaining <= 4:
        if opp_c > opp_d + 3:
            return 'D'
        if opp_c > opp_d:
            return 'D'
        return 'C'

    # If opponent just defected
    if last_opp == 'D':
        # Count consecutive opponent defections at end
        streak_d = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                streak_d += 1
            else:
                break
        # Long streak: defect
        if streak_d >= 3:
            return 'D'
        # If opponent has been mostly cooperative overall, forgive quickly
        if opp_d <= opp_c and streak_d == 1:
            if n >= 2 and history[n - 2][1] == 'C':
                # isolated defection after cooperation: retaliate once
                return 'D'
            return 'C'
        # Streak of 1-2: retaliate but plan to forgive
        if streak_d <= 2:
            if my_c >= 3 and opp_c >= 3 and opp_d <= opp_c + 2:
                # ongoing cooperation: retaliate once then forgive next round
                if last_me == 'C':
                    return 'D'
                return 'C'
            return 'D'
        return 'D'

    # Opponent just cooperated
    if last_opp == 'C':
        # If we defected last and opponent cooperated, consider returning to C
        if last_me == 'D':
            # If heavily cooperative opponent, return to cooperation to preserve gains
            if opp_c >= n - 2 and n >= 4:
                return 'C'
            # If we've been defecting too much, restore
            my_d = n - my_c
            if my_d >= my_c:
                return 'C'
            # Occasionally continue exploiting if opponent very forgiving
            if opp_d == 0:
                return 'C'
            if rng.random() < 0.25 and remaining > 15:
                return 'D'
            return 'C'
        # If mutual cooperation likely, continue
        if opp_d == 0:
            return 'C'
        # If opponent has been mostly cooperating, stay cooperative
        if opp_c >= opp_d + 2:
            return 'C'
        # Noisy TFT-like: if opponent mirrors us often, mirror back
        if rlen >= 5 and recent_same >= rlen - 1:
            return 'C'
        # If opponent's defection level moderate, mix
        if opp_d > opp_c:
            if rng.random() < 0.55:
                return 'D'
            return 'C'
        # Default cooperate
        return 'C'

    return 'C'
